{
  "aggregate_id": "DEF-NRS-484A-130::motor_vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition expressly excepts."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle, matching the admitting words without a class-removing exception."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a self-propelled vehicle."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial mass or licensing does not establish the self-propulsion required by the admitting clause."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The definition expressly excludes electric bicycles."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The definition expressly excludes electric scooters."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Emergency designation does not establish that the vehicle is self-propelled."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting function and emergency-vehicle sub-kind do not establish self-propulsion."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The jurisdiction-classified moped contract and quoted motor-driven definition establish a self-propelled road vehicle, while the moped definition excludes electric bicycles and scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract expressly requires a self-propelled nonrail vehicle and separates out the powered classes addressed by the exceptions."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle, and no exception names or describes the motorcycle class."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official or contracted road service and identifying equipment do not establish self-propulsion."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person, including a wheelchair or qualifying-device user, rather than the self-propelled device itself."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person with specified assistance rather than a self-propelled vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The requirement that a motor vehicle not be operated upon rails excludes the contract's on-track equipment."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose contract expressly makes it a motor vehicle, with no applicable class-removing exception."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "A marked passenger vehicle for hire is not required by its contract to be self-propelled."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Although the bus branch supplies motor-vehicle characteristics, the alternative lengthened passenger vehicle for hire is not required to be self-propelled."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Every admitted member must itself be a self-propelled nonrail vehicle fitting the quoted motor-vehicle contract or the separately classified motorcycle or moped contracts, with electric bicycles and scooters expressly excluded."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose contract expressly makes it a motor vehicle, and transit service introduces no applicable exception."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle for carrying goods, matching the admitting words without a class-removing exception."
    }
  ]
}

